-- GENERADO: no editar a mano.
-- Fuente: USDA FoodData Central, SR Legacy (https://fdc.nal.usda.gov/fdc-datasets/FoodData_Central_sr_legacy_food_csv_2018-04.zip); valores por 100 g.
-- Nombres en español traducidos con claude-haiku-5-5 (name_es_auto = true).
-- Regenerar con: node supabase/seed/foods/build-usda-sql.mjs
-- Generado: 2026-11-09. 1200 alimentos.
on conflict (id) do update set
  name_es = excluded.name_es,
  name_en = excluded.name_en,
  source = excluded.source,
  source_ref = excluded.source_ref,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  fiber_g = excluded.fiber_g,
  default_portion_g = excluded.default_portion_g,
  tags = excluded.tags,
  verified = excluded.verified,
  name_es_auto = excluded.name_es_auto;
